 if(kind=='png')ragg::agg_png(path,width=BW,height=BH,units='mm',res=400,background='white')else bf_pdf_open(path,BW,BH,font)
 ok<-FALSE;on.exit({dev.off();if(!ok)unlink(path)},add=TRUE);metrics<-file.path(W,paste0(kind,'-layout-metrics.json'));draw_panels(links,loci,metrics);m<-jsonlite::fromJSON(metrics,simplifyVector=FALSE)
